SELECT m.id, m.provider_id, m.global_id, m.link_id, m.thread_id, m.provider_thread_id, m.replying_to_id, m.provider_history_id, m.internal_date_ts, m.snippet, m.size_estimate, m.subject, m.from_name, m.from_contact_id, m.sent_at, m.has_attachments, m.is_read, m.is_starred, m.is_sent, m.is_draft, NULL::TEXT as body_text, NULL::TEXT as body_html_sanitized, NULL::TEXT as body_macro, m.headers_jsonb, m.created_at, m.updated_at FROM email_messages m WHERE m.provider_id = $1 AND m.link_id = $2
